head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07390";
scwin.form = null;
scwin.maxLenCheckVars = undefined;
scwin.maxLenCheckNames = undefined;
scwin.maxLenCheckMax = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_bzProcsNo_2", fn: function () { return String((dma_pageContext.get("bzProcsNo") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();
        try {
            const resultLen = $c.util.getComponent('dlt_resultList').getRowCount();
            for (let i = 0; i < resultLen; i++) {
                if (i < (resultLen - 1)) {
                    if (scwin.form.pershrInvstSaleTotDsp[i] == null) {

                    } else {

                    }
                }
            }
        } catch (err) { $c.exception.handleError(err, { notify: 'none', context: 'jldstf07390' }); }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07390.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07390' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldstf07390: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.maxLenCheckVars =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07390' }); }

try { scwin.maxLenCheckNames =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07390' }); }

try { scwin.maxLenCheckMax =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07390' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07390.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = function(e){
    try {
        fn_print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07390.btn_print_onclick' }); }
};

/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.loadCapital(r["bzProcsNo"], r["clmInstSeq"], r["comNm"], r["invstChgTpCd"], r["invstDd"], r["invstSaleShrs"], r["pershrInvstSaleAmt"], r["stkNm"], r["incdecRsn"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    try {
        scwin.form = (document.prelistEtcForm || { elements: [] });
        if (($c.util.getComponent("ipt_nowPage").getValue()) > ($c.util.getComponent("ipt_billLstSaveStatCd").getValue())) {
            return;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07390.onload" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_resultList_fmt_invstDd
 * @description grd result List fmt invst Dd 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_fmt_invstDd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "bzProcsNo") ?? '') : '');
        if (v !== 'SUMPART') { return String((dl && dl.getCellData ? dl.getCellData(r, "invstDd") : '') ?? ''); }
        if (v === 'SUMPART') { return "소계"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_resultList.invstDd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name loadCapital
 * @description load Capital 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} clmInstSeq clmInstSeq
 * @param {String} comNm comNm
 * @param {String} invstChgTpCd invstChgTpCd
 * @param {String} invstDd invstDd
 * @param {*} invstSaleShrs invstSaleShrs
 * @param {*} pershrInvstSaleAmt pershrInvstSaleAmt
 * @param {String} stkNm stkNm
 * @param {*} incdecRsn incdecRsn
 * @returns {void}
 * @hidden N
 */
scwin.loadCapital = function (bzProcsNo, clmInstSeq, comNm, invstChgTpCd, invstDd, invstSaleShrs, pershrInvstSaleAmt, stkNm, incdecRsn) {
    if (bzProcsNo === "SUMPART") {
        return;
    }
    $c.util.getComponent("ipt_clmInstSeq").setValue(clmInstSeq);
    $c.util.getComponent('ipt_comNm').setValue(comNm);
    (($c.util.getComponent('slc_invstChgTpCd'))?.setValue?.(invstChgTpCd));
    $c.util.getComponent('ipt_invstDd').setValue($c.date.dateUnFormat(invstDd));
    $c.util.getComponent('ipt_invstSaleShrs').setValue($c.num.formatNumber(invstSaleShrs));
    $c.util.getComponent('ipt_pershrInvstSaleAmt').setValue($c.num.formatNumber(pershrInvstSaleAmt));
    (($c.util.getComponent('slc_stkNm'))?.setValue?.(stkNm));
    (($c.util.getComponent('slc_incdecRsn'))?.setValue?.(incdecRsn));
};

/**
 * @method
 * @name setDataMergeDate
 * @description set Data Merge Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataMergeDate = function () {
    /* empty */
};
